/* =====================================================================
   app2_1_views_tests.sql   APP-2 stage 1: field-ownership and equipment-search views, then their tests
   GENERATED by tools/bundle_sql.py from the files listed below. Do not edit:
   change the source file and run `python tools/bundle_sql.py` again.
   Paste the whole file into New query of the ATLAS_SQL_DB item (type SQL database),
   run it once, and copy the Messages tab. Each file runs in its own batch.
   Files, in run order:
     db/views/vw_field_ownership.sql
     db/views/vw_equipment_search.sql
     db/tests/t_field_ownership.sql
     db/tests/t_equipment_search.sql
   ===================================================================== */
SET NOCOUNT ON;
PRINT N'=== app2_1_views_tests: 4 file(s) ===';

PRINT N'--- db/views/vw_field_ownership.sql';
EXEC (N'/* =====================================================================
   app.vw_field_ownership       APP-2 step 0 (left over from APP-1, decided 14 Nov);
                                FINAL PLAN/09 section 9; screens S-5 and S-13
   Single statement per file; CREATE OR ALTER, safe to run again.

   One row per active catalogue field: which role answers first (responsible) and which
   role signs off second (accountable) when someone changes that field. S-5 shows these
   next to every field ("show the responsible and accountable owner next to each editable
   field", POC-APP-03); S-13''s Field governance tab reads the same rows later (APP-9).

   Why a view and not a table: the owners follow from the routes in app.approval_route.
   A second table could disagree with them (09 section 10).

   Which route a field uses: the same choice as app.usp_route_resolve when no class is
   known. Among the active UPDATE routes for the field''s entity type that cover any class
   (class_scope = ''ANY''), a route naming this field beats the wildcard route (''*''); on a
   tie the lowest route_id wins. Routes limited to a list of classes (for example PSV or
   pump classes) are left out on purpose: they depend on the class of the item being
   changed, which a catalogue field does not have. For a heater none of the client''s
   class routes applies [REF-46:L0210-L0223]. If the client ever adds a HEATER class
   route, this view has to take the class as an input (then it becomes a function).

   Roles, not groups: the group that answers depends on the profit centre of the heater,
   so it is chosen at request time (app.fn_group_for_role). An alias such as
   "Operations-IOC - NMD" is shown as the role it stands for (app.role_alias).

   responsible_role, accountable_role and route_id are NULL when no route matches (the
   field is then UNROUTED and admins see it on S-13).

   Key: field_ownership_key = entity_type + ''|'' + field_code, never NULL. ISNULL is the
   OUTERMOST function on purpose: SQL Server reports a column as not nullable only then
   (found 14 Nov, B2: ISNULL inside a CAST was reported as nullable). Exposed through
   the connector: explicit lengths everywhere, no nvarchar(max).
   ===================================================================== */
CREATE OR ALTER VIEW app.vw_field_ownership
AS
SELECT
    ISNULL(CAST(c.entity_type + N''|'' + c.field_code AS nvarchar(80)), N'''') AS field_ownership_key,
    CAST(c.entity_type  AS nvarchar(10))  AS entity_type,
    CAST(c.field_code   AS nvarchar(64))  AS field_code,
    CAST(c.label        AS nvarchar(100)) AS label,
    CAST(COALESCE(ra.role_name, rt.responsible_role) AS nvarchar(64)) AS responsible_role,
    CAST(COALESCE(aa.role_name, rt.accountable_role) AS nvarchar(64)) AS accountable_role,
    CAST(rt.route_id    AS int)           AS route_id
FROM app.field_catalog AS c
OUTER APPLY
(
    SELECT TOP (1) r.route_id, r.responsible_role, r.accountable_role
    FROM app.approval_route AS r
    WHERE r.is_active = 1
      AND r.entity_type = c.entity_type
      AND r.request_action = N''UPDATE''
      AND r.class_scope = N''ANY''
      AND (r.field_or_characteristic = N''*'' OR r.field_or_characteristic = c.field_code)
    ORDER BY CASE WHEN r.field_or_characteristic <> N''*'' THEN 1 ELSE 0 END DESC, r.route_id
) AS rt
LEFT JOIN app.role_alias AS ra ON ra.alias_name = rt.responsible_role
LEFT JOIN app.role_alias AS aa ON aa.alias_name = rt.accountable_role
WHERE c.is_active = 1;
');

PRINT N'--- db/views/vw_equipment_search.sql';
EXEC (N'/* =====================================================================
   app.vw_equipment_search      APP-2; FINAL PLAN/09 section 9; screens S-4 (search),
                                S-6 (field view finds a heater with it)
   Single statement per file; CREATE OR ALTER, safe to run again.

   One row per heater: every column of gold.vw_equipment_current (FINAL PLAN/01 section
   6.1, in the same order, same names, same types) plus three counters for the result list:

     open_request_count  change requests on this heater that are still open (status not
                         APPROVED, REJECTED or CANCELLED), counting requests on the heater
                         itself and requests on its functional location (FLOC)
     invalid_rule_count  NULL until APP-5. It will count the published rules whose latest
                         successful run flags this heater (app.vw_equipment_rule_status).
                         NULL means "not computed yet", not zero: the screen shows a dash
                         ("blank values show as blank, never as zero", REF-13 to 21).
                         APP-5 replaces this one line with the real count.
     verification_pct    gold.vw_verification_score.verification_pct (0 to 100), NULL when
                         the heater has no score row

   The gold columns are listed without a CAST on purpose: they keep exactly the types the
   contract gives them (db/tests/t_gold_contract.sql guards that), so a longer value from
   the data engineer can never be cut short here. t_equipment_search.sql checks the types.

   Key: equipment_id (ISNULL makes the view report it as never NULL, which the connector
   needs for a declared key). Exposed through the connector: no nvarchar(max).
   Reads gold.vw_equipment_current, gold.vw_verification_score and app.change_request.
   ===================================================================== */
CREATE OR ALTER VIEW app.vw_equipment_search
AS
SELECT
    ISNULL(e.equipment_id, 0) AS equipment_id,
    e.equipment_number,
    e.equipment_description,
    e.functional_location,
    e.floc_description,
    e.superior_functional_location,
    e.equipment_tag_number,
    e.equip_class,
    e.class_type,
    e.object_type,
    e.floc_class,
    e.tech_object_type,
    e.manufacturer,
    e.model_number,
    e.manufacturer_serial_number,
    e.fired_unfired,
    e.heat_duty_mmbtu_hr,
    e.heat_duty_source,
    e.equipment_user_status,
    e.floc_user_status,
    e.profit_center_name,
    e.planner_group,
    e.heater_population_method,
    e.golden_version_id,
    e.last_changed_at_utc,
    e.baseline_as_of_utc,
    CAST(ISNULL(oc.n, 0) AS int)  AS open_request_count,
    CAST(NULL AS int)             AS invalid_rule_count,
    v.verification_pct            AS verification_pct
FROM gold.vw_equipment_current AS e
OUTER APPLY
(
    SELECT COUNT(*) AS n
    FROM app.change_request AS r
    WHERE r.request_status <> N''APPROVED''
      AND r.request_status <> N''REJECTED''
      AND r.request_status <> N''CANCELLED''
      AND (r.equipment_id = e.equipment_id
           OR (r.entity_type = N''FLOC'' AND r.functional_location = e.functional_location))
) AS oc
LEFT JOIN gold.vw_verification_score AS v ON v.equipment_id = e.equipment_id;
');

PRINT N'--- db/tests/t_field_ownership.sql';
EXEC (N'/* =====================================================================
   t_field_ownership.sql     APP-2 test: app.vw_field_ownership
   Needs : migrations 0001-0007, seeds 0101-0107, procs fn_group_for_role and
           usp_route_resolve, view vw_field_ownership.
   Reads only. Needs no local seed (no people) and leaves nothing behind.
   Final line: `t_field_ownership RESULT: ...`

   Checks
     O1  the view exists, has exactly the 7 columns of 09 section 9 with the right types,
         and no (max) column
     O2  one row per active catalogue field, key unique, never NULL (reported as not nullable)
     O3  every catalogue field has a route (the wildcard routes of REF-46 cover all 13)
     O4  the view agrees with app.usp_route_resolve for every field: same route and the
         same two roles (the procedure is asked without a class, as the view assumes)
     O5  two known answers: HEAT_DUTY is answered first by Operations-IOC (the alias
         "Operations-IOC - NMD" resolved) and signed off by SAPBusinessSupport; the FLOC
         field FLOC_CLASS also resolves (FLOC wildcard route)
   ===================================================================== */
SET NOCOUNT ON;

IF CAST(SERVERPROPERTY(''EngineEdition'') AS int) = 11
   OR @@VERSION LIKE N''%Data Warehouse%''
   OR DB_NAME() NOT LIKE N''ATLAS[_]SQL[_]DB%''
BEGIN
    PRINT ''FAIL t_field_ownership wrong editor: connected to "'' + DB_NAME() + ''". Open the item named ATLAS_SQL_DB whose type is SQL database. Nothing was run.'';
    RETURN;
END
IF OBJECT_ID(N''app.vw_field_ownership'', N''V'') IS NULL OR OBJECT_ID(N''app.usp_route_resolve'', N''P'') IS NULL
BEGIN
    PRINT ''FAIL t_field_ownership app.vw_field_ownership or app.usp_route_resolve is missing: run the APP-2 views stage (and the APP-1 procs) first. Nothing was run.'';
    RETURN;
END
IF (SELECT COUNT(*) FROM app.field_catalog) = 0 OR (SELECT COUNT(*) FROM app.approval_route) = 0
BEGIN
    PRINT ''FAIL t_field_ownership the catalogue or the routes are not loaded: run seeds 0103 and 0106 first. Nothing was run.'';
    RETURN;
END

DECLARE @checks int = 0, @fails int = 0;
DECLARE @n int, @n2 int, @problems nvarchar(2000), @nullable varchar(10);

/* ---- O1 columns and types -------------------------------------------------- */
DECLARE @exp TABLE (col_name sysname NOT NULL PRIMARY KEY, col_type nvarchar(40) NOT NULL);
INSERT INTO @exp (col_name, col_type) VALUES
    (N''field_ownership_key'', N''nvarchar(80)''),
    (N''entity_type'',         N''nvarchar(10)''),
    (N''field_code'',          N''nvarchar(64)''),
    (N''label'',               N''nvarchar(100)''),
    (N''responsible_role'',    N''nvarchar(64)''),
    (N''accountable_role'',    N''nvarchar(64)''),
    (N''route_id'',            N''int'');

DECLARE @d TABLE (column_ordinal int NULL, name sysname NULL, system_type_name nvarchar(256) NULL, is_nullable bit NULL, error_message nvarchar(4000) NULL);

BEGIN TRY
    INSERT INTO @d (column_ordinal, name, system_type_name, is_nullable, error_message)
    SELECT column_ordinal, name, system_type_name, is_nullable, error_message
    FROM sys.dm_exec_describe_first_result_set(N''SELECT * FROM app.vw_field_ownership'', NULL, 0);

    SET @checks += 1;
    SET @problems = NULL;
    IF EXISTS (SELECT 1 FROM @d WHERE error_message IS NOT NULL)
        SELECT TOP (1) @problems = N''SQL Server cannot describe the view: '' + error_message FROM @d WHERE error_message IS NOT NULL;
    ELSE
        SELECT @problems = STRING_AGG(CAST(x.msg AS nvarchar(max)), N''; '')
        FROM
        (
            SELECT e.col_name + N'': '' + CASE WHEN d.name IS NULL THEN N''missing'' ELSE N''type is '' + ISNULL(d.system_type_name, N''?'') + N'', expected '' + e.col_type END AS msg
            FROM @exp AS e
            LEFT JOIN @d AS d ON d.name COLLATE Latin1_General_BIN2 = e.col_name COLLATE Latin1_General_BIN2
            WHERE d.name IS NULL OR d.system_type_name <> e.col_type
            UNION ALL
            SELECT d.name + N'': not in 09 section 9'' FROM @d AS d
            WHERE NOT EXISTS (SELECT 1 FROM @exp AS e WHERE e.col_name COLLATE Latin1_General_BIN2 = d.name COLLATE Latin1_General_BIN2)
        ) AS x;
    IF @problems IS NULL PRINT ''OK  O1 vw_field_ownership has exactly the 7 columns of 09 section 9, with the right types'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL O1 columns: '' + LEFT(@problems, 1500); END

    SET @checks += 1;
    SELECT @n = COUNT(*) FROM @d WHERE system_type_name LIKE N''%(max)%'';
    IF @n = 0 PRINT ''OK  O1 no (max) column (the connector needs explicit lengths)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL O1 the view exposes '' + CAST(@n AS varchar(10)) + '' (max) column(s)''; END

    SET @checks += 1;
    SELECT @n = COUNT(*) FROM @d WHERE name = N''field_ownership_key'' AND is_nullable = 0;
    IF @n = 1 PRINT ''OK  O1 the key field_ownership_key is reported as not nullable (a declared key must not be)'';
    ELSE
    BEGIN
        SET @fails += 1;
        SELECT @nullable = CAST(is_nullable AS varchar(3)) FROM @d WHERE name = N''field_ownership_key'';
        PRINT ''FAIL O1 field_ownership_key is reported as nullable or is missing (is_nullable = '' + ISNULL(@nullable, ''column not found'') + '')'';
    END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL O1 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- O2 one row per active catalogue field ---------------------------------- */
BEGIN TRY
    SET @checks += 1;
    SELECT @n = COUNT(*) FROM app.field_catalog WHERE is_active = 1;
    SELECT @n2 = COUNT(*) FROM app.vw_field_ownership;
    IF @n = @n2 PRINT ''OK  O2 one row per active catalogue field: '' + CAST(@n2 AS varchar(10)) + '' of '' + CAST(@n AS varchar(10));
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL O2 the view has '' + CAST(@n2 AS varchar(10)) + '' rows, the catalogue has '' + CAST(@n AS varchar(10)) + '' active fields''; END

    SET @checks += 1;
    SELECT @n = COUNT(DISTINCT field_ownership_key), @n2 = COUNT(*) FROM app.vw_field_ownership;
    IF @n = @n2 AND NOT EXISTS (SELECT 1 FROM app.vw_field_ownership WHERE field_ownership_key = N'''')
        PRINT ''OK  O2 the key is unique and never empty'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL O2 the key is not unique or has an empty value ('' + CAST(@n AS varchar(10)) + '' distinct of '' + CAST(@n2 AS varchar(10)) + '')''; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL O2 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- O3 every field has a route --------------------------------------------- */
BEGIN TRY
    SET @checks += 1;
    SELECT @n = COUNT(*) FROM app.vw_field_ownership WHERE route_id IS NULL OR responsible_role IS NULL OR accountable_role IS NULL;
    IF @n = 0 PRINT ''OK  O3 every catalogue field has a route and two roles'';
    ELSE
    BEGIN
        SET @problems = NULL;
        SELECT @problems = STRING_AGG(field_code, N'', '') FROM app.vw_field_ownership WHERE route_id IS NULL OR responsible_role IS NULL OR accountable_role IS NULL;
        SET @fails += 1;
        PRINT ''FAIL O3 '' + CAST(@n AS varchar(10)) + '' field(s) have no route or no role: '' + LEFT(@problems, 1500);
    END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL O3 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- O4 agreement with app.usp_route_resolve -------------------------------- */
CREATE TABLE #r
(
    route_id int NULL, route_used nvarchar(12) NOT NULL,
    responsible_role nvarchar(64) NULL, responsible_group nvarchar(64) NOT NULL,
    accountable_role nvarchar(64) NULL, accountable_group nvarchar(64) NOT NULL
);

DECLARE @entity nvarchar(10), @field nvarchar(64), @v_route int, @v_resp nvarchar(64), @v_acc nvarchar(64);
DECLARE @p_route int, @p_resp nvarchar(64), @p_acc nvarchar(64), @bad nvarchar(400), @compared int = 0;

DECLARE f_cursor CURSOR LOCAL FAST_FORWARD FOR
    SELECT entity_type, field_code, route_id, responsible_role, accountable_role FROM app.vw_field_ownership ORDER BY field_code;
OPEN f_cursor;
FETCH NEXT FROM f_cursor INTO @entity, @field, @v_route, @v_resp, @v_acc;
WHILE @@FETCH_STATUS = 0
BEGIN
    SET @checks += 1;
    BEGIN TRY
        DELETE FROM #r;
        INSERT INTO #r (route_id, route_used, responsible_role, responsible_group, accountable_role, accountable_group)
        EXEC app.usp_route_resolve @entity_type = @entity, @request_action = N''UPDATE'', @profit_center_name = N''OP RES MB'', @field_code = @field, @class_code = NULL;
        SELECT @p_route = route_id, @p_resp = responsible_role, @p_acc = accountable_role FROM #r;

        SET @bad = NULL;
        IF ISNULL(@p_route, -1) <> ISNULL(@v_route, -1) SET @bad = N''route '' + ISNULL(CAST(@v_route AS nvarchar(12)), N''NULL'') + N'' in the view, '' + ISNULL(CAST(@p_route AS nvarchar(12)), N''NULL'') + N'' from the procedure'';
        ELSE IF ISNULL(@p_resp, N'''') <> ISNULL(@v_resp, N'''') SET @bad = N''responsible role '' + ISNULL(@v_resp, N''NULL'') + N'' in the view, '' + ISNULL(@p_resp, N''NULL'') + N'' from the procedure'';
        ELSE IF ISNULL(@p_acc, N'''') <> ISNULL(@v_acc, N'''') SET @bad = N''accountable role '' + ISNULL(@v_acc, N''NULL'') + N'' in the view, '' + ISNULL(@p_acc, N''NULL'') + N'' from the procedure'';

        IF @bad IS NULL SET @compared += 1;
        ELSE BEGIN SET @fails += 1; PRINT ''FAIL O4 '' + @field + '': '' + @bad; END
    END TRY
    BEGIN CATCH
        SET @fails += 1;
        PRINT ''FAIL O4 '' + @field + '': error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
    END CATCH;
    FETCH NEXT FROM f_cursor INTO @entity, @field, @v_route, @v_resp, @v_acc;
END
CLOSE f_cursor;
DEALLOCATE f_cursor;
DROP TABLE #r;
PRINT ''INFO O4 fields where the view and app.usp_route_resolve agree: '' + CAST(@compared AS varchar(10));

/* ---- O5 two known answers (REF-46 wildcard routes) -------------------------- */
BEGIN TRY
    SET @checks += 1;
    SELECT @n = COUNT(*) FROM app.vw_field_ownership
    WHERE field_code = N''HEAT_DUTY'' AND responsible_role = N''Operations-IOC'' AND accountable_role = N''SAPBusinessSupport'';
    IF @n = 1 PRINT ''OK  O5 HEAT_DUTY: first answer Operations-IOC (alias resolved), sign-off SAPBusinessSupport'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL O5 HEAT_DUTY is not Operations-IOC / SAPBusinessSupport (alias "Operations-IOC - NMD" not resolved, or the wildcard route changed)''; END

    SET @checks += 1;
    SELECT @n = COUNT(*) FROM app.vw_field_ownership
    WHERE field_code = N''FLOC_CLASS'' AND entity_type = N''FLOC'' AND route_id IS NOT NULL AND accountable_role = N''SAPBusinessSupport'';
    IF @n = 1 PRINT ''OK  O5 FLOC_CLASS (a FLOC field) resolves through the FLOC wildcard route'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL O5 FLOC_CLASS does not resolve to the FLOC wildcard route with SAPBusinessSupport''; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL O5 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

IF @fails = 0 PRINT ''t_field_ownership RESULT: ALL '' + CAST(@checks AS varchar(10)) + '' CHECKS PASS'';
ELSE PRINT ''t_field_ownership RESULT: '' + CAST(@fails AS varchar(10)) + '' OF '' + CAST(@checks AS varchar(10)) + '' CHECK(S) FAILED'';
');

PRINT N'--- db/tests/t_equipment_search.sql';
EXEC (N'/* =====================================================================
   t_equipment_search.sql    APP-2 test: app.vw_equipment_search
   Needs : migrations 0001-0007, seeds 0101-0107, the gold views (the synthetic stub
           db/dev/gold_stub.sql or the data engineer''s real views) and the view
           app.vw_equipment_search.
   Inserts three synthetic change requests inside a transaction and ROLLS THEM BACK, so
   nothing is left behind (if app.change_request was empty before, the request-id counter
   is reset to 0 afterwards, so the first real request is still CR-000001).
   Final line: `t_equipment_search RESULT: ...`

   Checks
     E1  the view exists and carries the 26 columns of gold.vw_equipment_current (same
         names, same types) plus open_request_count int, invalid_rule_count int,
         verification_pct decimal(5,2); no (max) column; equipment_id is reported as not
         nullable (the connector''s declared key)
     E2  one row per heater: as many rows as gold.vw_equipment_current, equipment_id unique
         (a join that multiplied rows would show here)
     E3  open_request_count: an open request on a heater counts, a closed one does not, an
         open request on the heater''s FLOC counts   (synthetic heaters only)
     E4  verification_pct equals gold.vw_verification_score   (synthetic heaters only)
     E5  invalid_rule_count is still NULL for every heater (APP-5 replaces this check when
         the rules engine fills it)
   ===================================================================== */
SET NOCOUNT ON;

IF CAST(SERVERPROPERTY(''EngineEdition'') AS int) = 11
   OR @@VERSION LIKE N''%Data Warehouse%''
   OR DB_NAME() NOT LIKE N''ATLAS[_]SQL[_]DB%''
BEGIN
    PRINT ''FAIL t_equipment_search wrong editor: connected to "'' + DB_NAME() + ''". Open the item named ATLAS_SQL_DB whose type is SQL database. Nothing was run.'';
    RETURN;
END
IF OBJECT_ID(N''app.vw_equipment_search'', N''V'') IS NULL
BEGIN
    PRINT ''FAIL t_equipment_search app.vw_equipment_search is missing: run the APP-2 views stage first. Nothing was run.'';
    RETURN;
END
IF OBJECT_ID(N''gold.vw_equipment_current'', N''V'') IS NULL OR OBJECT_ID(N''gold.vw_verification_score'', N''V'') IS NULL OR OBJECT_ID(N''app.change_request'', N''U'') IS NULL
BEGIN
    PRINT ''FAIL t_equipment_search a gold view or app.change_request is missing: run the gold stub (or the real gold) and the migrations first. Nothing was run.'';
    RETURN;
END

DECLARE @checks int = 0, @fails int = 0;
DECLARE @n int, @n2 int, @problems nvarchar(2000);

DECLARE @g TABLE (column_ordinal int NULL, name sysname NULL, system_type_name nvarchar(256) NULL, is_nullable bit NULL, error_message nvarchar(4000) NULL);
DECLARE @s TABLE (column_ordinal int NULL, name sysname NULL, system_type_name nvarchar(256) NULL, is_nullable bit NULL, error_message nvarchar(4000) NULL);

/* ---- E1 columns and types --------------------------------------------------- */
BEGIN TRY
    INSERT INTO @g (column_ordinal, name, system_type_name, is_nullable, error_message)
    SELECT column_ordinal, name, system_type_name, is_nullable, error_message
    FROM sys.dm_exec_describe_first_result_set(N''SELECT * FROM gold.vw_equipment_current'', NULL, 0);
    INSERT INTO @s (column_ordinal, name, system_type_name, is_nullable, error_message)
    SELECT column_ordinal, name, system_type_name, is_nullable, error_message
    FROM sys.dm_exec_describe_first_result_set(N''SELECT * FROM app.vw_equipment_search'', NULL, 0);

    SET @checks += 1;
    SET @problems = NULL;
    IF EXISTS (SELECT 1 FROM @s WHERE error_message IS NOT NULL) OR EXISTS (SELECT 1 FROM @g WHERE error_message IS NOT NULL)
        SELECT TOP (1) @problems = N''SQL Server cannot describe a view: '' + error_message FROM (SELECT error_message FROM @s UNION ALL SELECT error_message FROM @g) AS m WHERE error_message IS NOT NULL;
    ELSE
        SELECT @problems = STRING_AGG(CAST(x.msg AS nvarchar(max)), N''; '')
        FROM
        (
            -- every gold contract column must be in the search view, same type, same place
            SELECT g.name + N'': '' + CASE WHEN s.name IS NULL THEN N''missing from the search view''
                                         WHEN s.system_type_name <> g.system_type_name THEN N''type '' + s.system_type_name + N'' in the search view, '' + g.system_type_name + N'' in gold''
                                         ELSE N''position '' + CAST(s.column_ordinal AS nvarchar(10)) + N'' in the search view, '' + CAST(g.column_ordinal AS nvarchar(10)) + N'' in gold'' END AS msg
            FROM @g AS g
            LEFT JOIN @s AS s ON s.name COLLATE Latin1_General_BIN2 = g.name COLLATE Latin1_General_BIN2
            WHERE g.name IN (N''equipment_id'', N''equipment_number'', N''equipment_description'', N''functional_location'', N''floc_description'',
                             N''superior_functional_location'', N''equipment_tag_number'', N''equip_class'', N''class_type'', N''object_type'',
                             N''floc_class'', N''tech_object_type'', N''manufacturer'', N''model_number'', N''manufacturer_serial_number'',
                             N''fired_unfired'', N''heat_duty_mmbtu_hr'', N''heat_duty_source'', N''equipment_user_status'', N''floc_user_status'',
                             N''profit_center_name'', N''planner_group'', N''heater_population_method'', N''golden_version_id'',
                             N''last_changed_at_utc'', N''baseline_as_of_utc'')
              AND (s.name IS NULL OR s.system_type_name <> g.system_type_name OR s.column_ordinal <> g.column_ordinal)
            UNION ALL
            -- the three counters
            SELECT c.col_name + N'': '' + CASE WHEN s.name IS NULL THEN N''missing'' ELSE N''type is '' + s.system_type_name + N'', expected '' + c.col_type END
            FROM (VALUES (N''open_request_count'', N''int''), (N''invalid_rule_count'', N''int''), (N''verification_pct'', N''decimal(5,2)'')) AS c (col_name, col_type)
            LEFT JOIN @s AS s ON s.name COLLATE Latin1_General_BIN2 = c.col_name COLLATE Latin1_General_BIN2
            WHERE s.name IS NULL OR s.system_type_name <> c.col_type
        ) AS x;
    IF @problems IS NULL PRINT ''OK  E1 the search view has the 26 gold columns (same names, types, order) and the 3 counters with the right types'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL E1 columns: '' + LEFT(@problems, 1500); END

    SET @checks += 1;
    SELECT @n = COUNT(*) FROM @s WHERE column_ordinal IS NOT NULL;
    IF @n = 29 PRINT ''OK  E1 exactly 29 columns (26 + 3)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL E1 the search view has '' + CAST(@n AS varchar(10)) + '' columns, expected 29 (09 section 9)''; END

    SET @checks += 1;
    SELECT @n = COUNT(*) FROM @s WHERE system_type_name LIKE N''%(max)%'';
    IF @n = 0 PRINT ''OK  E1 no (max) column (the connector needs explicit lengths)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL E1 the view exposes '' + CAST(@n AS varchar(10)) + '' (max) column(s)''; END

    SET @checks += 1;
    SELECT @n = COUNT(*) FROM @s WHERE name = N''equipment_id'' AND is_nullable = 0;
    IF @n = 1 PRINT ''OK  E1 the key equipment_id is reported as not nullable (a declared key must not be)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL E1 equipment_id is reported as nullable or is missing''; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL E1 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- E2 one row per heater --------------------------------------------------- */
BEGIN TRY
    SET @checks += 1;
    SELECT @n = COUNT(*) FROM gold.vw_equipment_current;
    SELECT @n2 = COUNT(*) FROM app.vw_equipment_search;
    IF @n = @n2 PRINT ''OK  E2 as many rows as gold.vw_equipment_current: '' + CAST(@n2 AS varchar(10));
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL E2 the search view has '' + CAST(@n2 AS varchar(10)) + '' rows, gold.vw_equipment_current has '' + CAST(@n AS varchar(10)) + '' (a join multiplied or dropped rows)''; END

    SET @checks += 1;
    SELECT @n = COUNT(DISTINCT equipment_id) FROM app.vw_equipment_search;
    IF @n = @n2 PRINT ''OK  E2 equipment_id is unique'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL E2 equipment_id has '' + CAST(@n AS varchar(10)) + '' distinct values in '' + CAST(@n2 AS varchar(10)) + '' rows''; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL E2 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- E3 open_request_count (synthetic heaters only) -------------------------- */
DECLARE @idA int, @idB int, @flocB nvarchar(40), @baseA int, @baseB int, @gotA int, @gotB int, @was_empty bit;

SELECT @idA = equipment_id FROM gold.vw_equipment_current WHERE equipment_number = N''SYN-EQ-0004'';
SELECT @idB = equipment_id, @flocB = functional_location FROM gold.vw_equipment_current WHERE equipment_number = N''SYN-EQ-0005'';

IF @idA IS NULL OR @idB IS NULL
    PRINT ''INFO E3 the synthetic heaters SYN-EQ-0004 and SYN-EQ-0005 are not in gold (the real gold is loaded): the request-counter check is skipped. Re-create the stub or test counters with real requests after APP-3.'';
ELSE
BEGIN
    BEGIN TRY
        SET @checks += 1;
        SELECT @baseA = open_request_count FROM app.vw_equipment_search WHERE equipment_id = @idA;
        SELECT @baseB = open_request_count FROM app.vw_equipment_search WHERE equipment_id = @idB;
        SET @was_empty = CASE WHEN EXISTS (SELECT 1 FROM app.change_request) THEN 0 ELSE 1 END;

        BEGIN TRANSACTION;

        -- 1: an open request on heater A
        INSERT INTO app.change_request
            (entity_type, equipment_id, equipment_number, functional_location, profit_center_name, source_type, field_code,
             old_value, new_value, reason, requested_by, request_status, responsible_group, accountable_group, deduplication_key)
        VALUES
            (N''EQUIPMENT'', @idA, N''SYN-EQ-0004'', N''SYN-FL-0004'', N''ROCKIES-PRB'', N''MANUAL'', N''HEAT_DUTY'',
             N''1.5000'', N''1.7500'', N''SYNTHETIC test request (t_equipment_search)'', N''test.person@example.test'', N''PENDING_RESPONSIBLE'',
             N''Operations-IOC-Platteville'', N''SAPBusinessSupport'', REPLICATE(N''1'', 64));
        -- 2: a closed (approved) request on heater A: must not count
        INSERT INTO app.change_request
            (entity_type, equipment_id, equipment_number, functional_location, profit_center_name, source_type, field_code,
             old_value, new_value, reason, requested_by, request_status, responsible_group, accountable_group, deduplication_key)
        VALUES
            (N''EQUIPMENT'', @idA, N''SYN-EQ-0004'', N''SYN-FL-0004'', N''ROCKIES-PRB'', N''MANUAL'', N''HEAT_DUTY'',
             N''1.2500'', N''1.5000'', N''SYNTHETIC test request (t_equipment_search)'', N''test.person@example.test'', N''APPROVED'',
             N''Operations-IOC-Platteville'', N''SAPBusinessSupport'', REPLICATE(N''3'', 64));
        -- 3: an open request on the FLOC of heater B (no equipment id): counts for B
        INSERT INTO app.change_request
            (entity_type, equipment_id, equipment_number, functional_location, profit_center_name, source_type, field_code,
             old_value, new_value, reason, requested_by, request_status, responsible_group, accountable_group, deduplication_key)
        VALUES
            (N''FLOC'', NULL, NULL, @flocB, N''ROCKIES-PRB'', N''MANUAL'', N''FLOC_CLASS'',
             N''VESSEL_HEATER_TRTR'', N''HEATER'', N''SYNTHETIC test request (t_equipment_search)'', N''test.person@example.test'', N''PENDING_RESPONSIBLE'',
             N''Operations-IOC-Platteville'', N''SAPBusinessSupport'', REPLICATE(N''2'', 64));

        SELECT @gotA = open_request_count FROM app.vw_equipment_search WHERE equipment_id = @idA;
        SELECT @gotB = open_request_count FROM app.vw_equipment_search WHERE equipment_id = @idB;

        ROLLBACK TRANSACTION;

        IF @gotA = @baseA + 1 AND @gotB = @baseB + 1
            PRINT ''OK  E3 open_request_count: an open request counts (heater A '' + CAST(@baseA AS varchar(10)) + '' -> '' + CAST(@gotA AS varchar(10)) + ''), a closed one does not, an open request on the FLOC counts (heater B '' + CAST(@baseB AS varchar(10)) + '' -> '' + CAST(@gotB AS varchar(10)) + '')'';
        ELSE
        BEGIN
            SET @fails += 1;
            PRINT ''FAIL E3 open_request_count: heater A '' + CAST(@baseA AS varchar(10)) + '' -> '' + CAST(@gotA AS varchar(10)) + '' (expected +1), heater B '' + CAST(@baseB AS varchar(10)) + '' -> '' + CAST(@gotB AS varchar(10)) + '' (expected +1)'';
        END

        IF @was_empty = 1
        BEGIN
            BEGIN TRY
                DBCC CHECKIDENT (N''app.change_request'', RESEED, 0) WITH NO_INFOMSGS;
            END TRY
            BEGIN CATCH
                PRINT ''INFO E3 could not reset the request-id counter (error '' + CAST(ERROR_NUMBER() AS varchar(12)) + ''); the next real request may not be CR-000001.'';
            END CATCH;
        END
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        SET @fails += 1;
        PRINT ''FAIL E3 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE() + '' (the transaction was rolled back)'';
    END CATCH;
END

/* ---- E4 verification_pct (synthetic heaters only) ---------------------------- */
BEGIN TRY
    IF @idA IS NULL OR @idB IS NULL
        PRINT ''INFO E4 synthetic heaters not found: the verification check is skipped'';
    ELSE
    BEGIN
        SET @checks += 1;
        SELECT @n = COUNT(*)
        FROM app.vw_equipment_search AS s
        JOIN gold.vw_verification_score AS v ON v.equipment_id = s.equipment_id
        WHERE s.equipment_id IN (@idA, @idB) AND s.verification_pct = v.verification_pct;
        IF @n = 2 PRINT ''OK  E4 verification_pct equals gold.vw_verification_score for the two sample heaters'';
        ELSE BEGIN SET @fails += 1; PRINT ''FAIL E4 verification_pct differs from gold.vw_verification_score for a sample heater (matches: '' + CAST(@n AS varchar(10)) + '' of 2)''; END
    END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL E4 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

/* ---- E5 invalid_rule_count is not computed yet -------------------------------- */
BEGIN TRY
    SET @checks += 1;
    SELECT @n = COUNT(*) FROM app.vw_equipment_search WHERE invalid_rule_count IS NOT NULL;
    IF @n = 0 PRINT ''OK  E5 invalid_rule_count is NULL for every heater (APP-5 fills it; this check is replaced then)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL E5 '' + CAST(@n AS varchar(10)) + '' heater(s) have an invalid_rule_count: if APP-5 has delivered the real count, update this check''; END
END TRY
BEGIN CATCH
    SET @fails += 1;
    PRINT ''FAIL E5 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '': '' + ERROR_MESSAGE();
END CATCH;

IF @fails = 0 PRINT ''t_equipment_search RESULT: ALL '' + CAST(@checks AS varchar(10)) + '' CHECKS PASS'';
ELSE PRINT ''t_equipment_search RESULT: '' + CAST(@fails AS varchar(10)) + '' OF '' + CAST(@checks AS varchar(10)) + '' CHECK(S) FAILED'';
');

PRINT N'=== end of app2_1_views_tests ===';
